\begin{aligned}
B C^{2} &=\overrightarrow{B C}{^2}=(\overrightarrow{A C}-\overrightarrow{A B})^{2}=\overrightarrow{A C} \cdot(\overrightarrow{A C}-\overrightarrow{A B})-\overrightarrow{A B} \cdot(\overrightarrow{A C}-\overrightarrow{A B}) \\
&=\overrightarrow{A B}{^2}+\overrightarrow{A C}{^2}-2 \overrightarrow{A B} \cdot \overrightarrow{A C}=A B^{2}+A C^{2}-2 A B \cdot A C \cos A
\end{aligned}
